# ============================================================================
# FONCTIONS UTILITAIRES — TABLES DU MOMENT
# ============================================================================

def get_qx(age: int, sexe: str = "H", table: Optional[str] = None) -> float:
    """Retourne le qx officiel W-H pour un age et un sexe donnes."""
    if table in ("TH0002", "TGHF05H") or (table is None and sexe.upper() == "H"):
        t = QX_TH0002
    elif table in ("TF0002", "TGHF05F") or (table is None and sexe.upper() == "F"):
        t = QX_TF0002
    else:
        t = QX_TH0002
    age = max(0, min(age, 110))
    return t.get(age, 1.0)


def construire_lx(age_debut: int, duree: int, sexe: str = "H",
                  table: Optional[str] = None) -> list:
    """Construit la suite des probabilites de survie lx depuis age_debut."""
    lx = [1.0]
    for k in range(duree):
        qx = get_qx(age_debut + k, sexe, table)
        lx.append(lx[-1] * (1 - qx))
    return lx


def calculer_annuite_viagere(age: int, taux: float, sexe: str = "H",
                              table: Optional[str] = None,
                              omega: int = 110) -> float:
    """
    Calcule l'annuite viagere immediate a_x au taux technique donne.
    Utilise TH0002/TF0002 (table du moment).
    Pour EP-RE long terme, utiliser calculer_annuite_viagere_prospective().
    """
    if age >= omega:
        return 0.0
    v = 1 / (1 + taux)
    duree = omega - age
    lx = construire_lx(age, duree, sexe, table)
    return sum(lx[k] * (v ** k) for k in range(duree))


def calculer_probabilite_survie(age_debut: int, duree: int,
                                 sexe: str = "H",
                                 table: Optional[str] = None) -> float:
    """Calcule n_px = probabilite de survie de duree annees depuis age_debut."""
    lx = construire_lx(age_debut, duree, sexe, table)
    return lx[-1]


# ============================================================================
# FONCTIONS UTILITAIRES — TABLES GENERATIONNELLES (EP-RE LONG TERME)
# ============================================================================

def insee_qx_prospectif(age: int, annee: int, sexe: str = "H") -> float:
    """
    Retourne le qx prospectif INSEE pour un age et une annee donnes.
    Pour ages < 30 ou > 95 : extrapolation coherente.
    """
    d = QX_INSEE_H if sexe == "H" else QX_INSEE_F
    annee_cl = max(2007, min(int(annee), 2060))
    if age in d and annee_cl in d[age]:
        return d[age][annee_cl]
    if age < 30:
        qx_base = get_qx(age, sexe)
        taux = 0.015 if sexe == "H" else 0.010
        return qx_base * ((1 - taux) ** max(0, annee_cl - 2006))
    q95 = d.get(95, {}).get(annee_cl, d.get(95, {}).get(2060, 0.40))
    return min(float(q95) * (1.08 ** (age - 95)), 1.0)


def calculer_annuite_viagere_prospective(
    age: int, annee_retraite: int, sexe: str = "H",
    taux_actu: float = 0.0385, omega: int = 105
) -> float:
    """
    Calcule l'annuite viagere prospective en tenant compte de l'amelioration
    future de la mortalite (tables generationnelles INSEE 2014).
    Usage obligatoire : IAS 19, provisions Art.39/83/PER.
    """
    v = 1.0 / (1.0 + taux_actu)
    annuite = 0.0
    lx = 1.0
    for t in range(omega - age):
        annuite += (v ** t) * lx
        qx_t = insee_qx_prospectif(age + t, annee_retraite + t, sexe)
        lx *= (1.0 - qx_t)
    return annuite


